WITH sales AS ( SELECT "#" AS prod, "Descrição" AS desc, SUM("Qnt") AS total_units, CASE WHEN strftime('%m', "Emissão") BETWEEN '01' AND '02' THEN 1 WHEN strftime('%m', "Emissão") BETWEEN '03' AND '04' THEN 2 ELSE NULL END AS bimestre FROM vendas WHERE "Nota" <> 'NFe 2217' AND strftime('%Y', "Emissão") = strftime('%Y', 'now') GROUP BY prod, bimestre ) SELECT s1.prod, s1.desc, (s2.total_units - s1.total_units) AS diff_units FROM (SELECT prod, desc, total_units FROM sales WHERE bimestre = 1) s1 JOIN (SELECT prod, total_units FROM sales WHERE bimestre = 2) s2 ON s1.prod = s2.prod ORDER BY diff_units DESC LIMIT 1;